const html = $json.data || '';

if (!html) {
  return {
    json: {
      error: 'No HTML received'
    }
  };
}

// 1. Dynamically extract the category from the HTML <title> tag
// Your input has: <title data-rh=true>Task Automation Release Notes...
let categoryName = 'releaseNotes'; // Default fallback
const titleMatch = html.match(/<title[^>]*>(.*?)\s+Release Notes/i);

if (titleMatch) {
  // Extracts "Task Automation", trims spaces, and replaces inner spaces with underscores
  categoryName = titleMatch[1].trim().replace(/\s+/g, '_');
}

// 2. Extract the actual article content
const articleMatch = html.match(
  /<article[^>]*>([\s\S]*?)<\/article>/i
);

if (!articleMatch) {
  return {
    json: {
      error: 'Article content not found'
    }
  };
}

let content = articleMatch[1];

// 3. Remove feedback/navigation/unwanted elements
content = content
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<div[^>]*class=["'][^"']*doc-page-bottom-feedback-wrapper[^"']*["'][^>]*>[\s\S]*?<\/div>/gi, '');

// 4. Convert headings to readable text
content = content
  .replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n\n$1\n\n')
  .replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n\n$1\n\n')
  .replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n\n$1\n\n')
  .replace(/<h4[^>]*>([\s\S]*?)<\/h4>/gi, '\n\n$1\n\n');

// 5. Format lists and paragraphs
content = content
  .replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '\n• $1')
  .replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, '\n$1\n')
  .replace(/<br\s*\/?>/gi, '\n');

// 6. Remove all remaining HTML tags
content = content.replace(/<[^>]+>/g, ' ');

// 7. Decode common HTML entities
content = content
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&#x27;/gi, "'");

// 8. Clean up extra whitespace
content = content
  .replace(/[ \t]+/g, ' ')
  .replace(/[ \t]*\n[ \t]*/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// 9. Return the output using the dynamic key generated in Step 1
return {
  json: {
    releasenotes: content
  }
