const input = $json;

const releaseNotes = Array.isArray(input.releasenotes)
  ? input.releasenotes
  : [];

function cleanText(text) {
  return String(text || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .trim();
}

const notes = releaseNotes
  .map(cleanText)
  .filter(Boolean);

const fullSource = notes.join('\n\n');

// Dynamically determine month/year
let month = input.month || '';
let year = input.year || '';

if (!month || !year) {
  const url = input.url || input.link || '';

  const monthMatch = url.match(/[?&]month=([^&]+)/i);
  const yearMatch = url.match(/[?&]year=(\d{4})/i);

  if (monthMatch) {
    month = decodeURIComponent(monthMatch[1]);
  }

  if (yearMatch) {
    year = yearMatch[1];
  }
}

// If still unavailable, detect from source
if (!month || !year) {
  const dateMatch = fullSource.match(
    /\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+20\d{2}\b/i
  );

  if (dateMatch) {
    const parts = dateMatch[0].split(/\s+/);
    month = month || parts[0];
    year = year || parts[1];
  }
}

const releasePeriod = [month, year]
  .filter(Boolean)
  .join(' ');

return {
  json: {
    title: 'Boomi Enterprise Platform',
    releasePeriod,
    sourceReleaseNotes: fullSource,
    releaseNotes: notes
  }
};

const input = $input.all();

const FONT = 'Times New Roman';

const output = {
  sections: []
};

const section = {
  paragraphs: []
};

// =====================================================
// STATE
// =====================================================

let lastHeading = '';
let lastWasContent = false;

// =====================================================
// CLEANING FUNCTIONS
// =====================================================

function cleanText(value) {
  return String(value || '')
    .replace(/\r/g, '')
    .replace(/\u00a0/g, ' ')
    // Remove anything inside parentheses
    .replace(/\s*\([^)]*\)/g, ' ')
    // Normalize spaces
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function cleanLine(value) {
  return cleanText(value)
    .replace(/^[-–—]\s*/, '')
    .trim();
}

// =====================================================
// REFER TO DETECTION
// =====================================================

function isReferToLine(line) {
  const value = String(line || '')
    .trim()
    .replace(/^[•●▪◦]\s*/, '')
    .replace(/^[-–—]\s*/, '')
    .trim();

  return /^refer\s+to\b/i.test(value);
}

// =====================================================
// READ MORE DETECTION & SPLITTING
// =====================================================

function containsReadMore(text) {
  return /read[\s\u00a0]+more(?:[\s\u00a0]*[›>»])?/i.test(String(text || ''));
}

function splitReadMore(text) {
  return String(text || '')
    .split(/read[\s\u00a0]+more(?:[\s\u00a0]*[›>»])?/gi)
    .map(part => cleanText(part))
    .filter(Boolean);
}

// =====================================================
// PARAGRAPH HELPER
// =====================================================

function addParagraph(text, options = {}) {
  const value = cleanText(text);

  if (!value) {
    return;
  }

  section.paragraphs.push({
    children: [
      {
        text: value,
        font: FONT,
        ...options
      }
    ]
  });
}

// =====================================================
// MAIN STATIC DOCUMENT HEADING
// =====================================================

function addMainDocumentHeading() {
  addParagraph('Boomi Platform Release updates', {
    font: FONT,
    size: 32,
    bold: true,
    alignment: 'center'
  });

  lastHeading = 'Boomi Platform Release updates';
  lastWasContent = false;

  addSpacing(12);
}

// =====================================================
// DOCUMENT ELEMENTS
// =====================================================

function addProductHeading(text) {
  const value = cleanText(text);
  if (!value || lastHeading === value) return;

  addParagraph(value, {
    font: FONT,
    size: 32,
    bold: true,
    alignment: 'left'
  });

  lastHeading = value;
  lastWasContent = false;
}

function addSectionHeading(text) {
  const value = cleanText(text);
  if (!value || lastHeading === value) return;

  addParagraph(value, {
    font: FONT,
    size: 24,
    bold: true,
    alignment: 'left'
  });

  lastHeading = value;
  lastWasContent = false;
}

function addSubHeading(text) {
  const value = cleanText(text);
  if (!value || lastHeading === value) return;

  addParagraph(value, {
    font: FONT,
    size: 28,
    bold: true,
    alignment: 'left'
  });

  lastHeading = value;
  lastWasContent = false;
}

function addBody(text) {
  const value = cleanText(text);
  if (!value) return;

  addParagraph(value, {
    font: FONT,
    size: 22,
    alignment: 'Justify'
  });

  lastWasContent = true;
}

function addBullet(text) {
  let value = cleanText(text);
  if (!value) return;

  // Remove existing bullet symbol
  value = value.replace(/^[•●▪◦]\s*/, '').trim();
  if (!value) return;

  addParagraph(`• ${value}`, {
    font: FONT,
    size: 22,
    alignment: 'Justify'
  });

  lastWasContent = true;
}

function addNote(text) {
  const value = cleanText(text);
  if (!value) return;

  addParagraph(value, {
    font: FONT,
    size: 22,
    italic: true,
    alignment: 'Justify'
  });

  lastWasContent = false;
}

function addUpdated(text) {
  const value = cleanText(text);
  if (!value) return;

  addParagraph(value, {
    font: FONT,
    size: 18,
    italic: true,
    alignment: 'Justify'
  });

  lastWasContent = false;
}

function addReleaseDate(text) {
  const value = cleanText(text);
  if (!value) return;

  addParagraph(value, {
    font: FONT,
    size: 22,
    // bold: true,
    alignment: 'left'
  });

  lastWasContent = false;
}

function addSpacing(size = 10) {
  if (section.paragraphs.length === 0) return;

  section.paragraphs.push({
    children: [
      {
        text: '',
        font: FONT,
        size
      }
    ]
  });

  lastWasContent = false;
}

// =====================================================
// CHECK FUNCTIONS
// =====================================================

function isBullet(line) {
  const value = String(line || '').trim();
  return (
    value.startsWith('•') ||
    value.startsWith('●') ||
    value.startsWith('▪') ||
    value.startsWith('◦')
  );
}

function isEmptyBullet(line) {
  const value = String(line || '').trim();
  return (
    value === '•' ||
    value === '●' ||
    value === '▪' ||
    value === '◦'
  );
}

function isNoUpdates(line) {
  const value = cleanText(line).toLowerCase();
  return (
    value === 'no updates' ||
    value === 'no update' ||
    value === 'no changes' ||
    value === 'none'
  );
}

function isSectionHeading(line) {
  const value = cleanText(line).toLowerCase();
  const headings = new Set([
    'new feature',
    'new features',
    'enhancement',
    'enhancements',
    'fix',
    'fixes',
    'known issue',
    'known issues',
    'observability enhancements',
    'java and docker updates',
    'other updates',
    'enhancement and fixes',
    'enhancements and fixes'
  ]);

  return headings.has(value);
}

function isPlatformRelease(line) {
  return /^platform release$/i.test(cleanText(line));
}

function isReleaseDate(line) {
  return /^([A-Z][a-z]+)\s+\d{1,2}\s+\d{4}$/i.test(cleanText(line));
}

function isUpdated(line) {
  return /^updated\s+/i.test(cleanText(line));
}

function isGlobalTitle(line) {
  const value = cleanText(line);
  return (
    /^boomi enterprise platform$/i.test(value) ||
    /^(january|february|march|april|may|june|july|august|september|october|november|december)\s+\d{4}$/i.test(value) ||
    /^boomi enterprise platform\s+.+\s+release notes?/i.test(value)
  );
}

function isProductHeading(lines, index) {
  const line = cleanText(lines[index]);
  if (!line) return false;
  if (/release notes?\s+for/i.test(line)) return true;

  if (
    isGlobalTitle(line) ||
    isSectionHeading(line) ||
    isPlatformRelease(line) ||
    isReleaseDate(line) ||
    isUpdated(line) ||
    isNoUpdates(line) ||
    isReferToLine(line)
  ) {
    return false;
  }

  if (line.length > 100) return false;

  for (let i = index + 1; i < Math.min(index + 5, lines.length); i++) {
    const next = cleanText(lines[i]);
    if (!next) continue;
    if (isSectionHeading(next) || isPlatformRelease(next) || isReleaseDate(next)) {
      return true;
    }
    break;
  }

  return false;
}

function isSubHeading(lines, index) {
  const line = cleanText(lines[index]);
  if (!line) return false;

  if (
    isGlobalTitle(line) ||
    isSectionHeading(line) ||
    isPlatformRelease(line) ||
    isReleaseDate(line) ||
    isUpdated(line) ||
    isNoUpdates(line) ||
    isReferToLine(line)
  ) {
    return false;
  }

  if (/release notes?\s+for/i.test(line)) return false;
  if (line.length > 100) return false;

  for (let i = index + 1; i < Math.min(index + 4, lines.length); i++) {
    const next = cleanText(lines[i]);
    if (!next) continue;
    if (isSectionHeading(next)) return true;
    break;
  }

  return false;
}

function extractCategory(text) {
  const value = cleanText(text);
  const match = value.match(/^(.+?)\s+Release Notes?\s+for\s+/i);
  return match ? cleanText(match[1]) : '';
}

function getReleaseTitleCategory(line) {
  const category = extractCategory(line);
  return category || cleanText(line);
}

// =====================================================
// SUMMARY DOCUMENT
// =====================================================

function processSummaryDocument(data) {
  const releaseNotes = String(data.releaseNotes || '')
    .replace(/\r/g, '')
    .trim();

  if (!releaseNotes) return;

  const lines = releaseNotes.split('\n');
  let currentBullet = '';

  function flushBullet() {
    if (!currentBullet) return;

    if (containsReadMore(currentBullet)) {
      const parts = splitReadMore(currentBullet);
      for (const part of parts) {
        addBullet(part);
      }
    } else {
      addBullet(currentBullet);
    }

    currentBullet = '';
  }

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = cleanLine(rawLine);

    if (!line) continue;

    if (isReferToLine(rawLine)) {
      flushBullet();
      continue;
    }

    if (isGlobalTitle(line)) continue;

    if (isUpdated(line)) {
      flushBullet();
      addUpdated(line);
      continue;
    }

    if (isPlatformRelease(line) || isReleaseDate(line)) {
  flushBullet();

  if (isReleaseDate(line)) {
    addReleaseDate(line);
  }

  continue;
}

    if (isSectionHeading(line)) {
      flushBullet();
      addSectionHeading(line);
      continue;
    }

    if (isEmptyBullet(rawLine)) {
      flushBullet();
      continue;
    }

    // Line containing "Read more ›" -> flush and output each section as a bullet
    if (containsReadMore(line)) {
      flushBullet();
      const parts = splitReadMore(line);
      for (const part of parts) {
        addBullet(part);
      }
      continue;
    }

    if (isBullet(rawLine)) {
      flushBullet();
      currentBullet = cleanText(line.replace(/^[•●▪◦]\s*/, ''));
      continue;
    }

    if (currentBullet) {
      currentBullet += ' ' + line;
      continue;
    }

    // Introductory body paragraphs
    addBody(line);
  }

  flushBullet();
}

// =====================================================
// NORMAL RELEASE NOTE DOCUMENT
// =====================================================

function processNormalDocument(data) {
  const releaseNotes = String(data.releaseNotes || '')
    .replace(/\r/g, '')
    .trim();

  if (!releaseNotes) return;

  const lines = releaseNotes.split('\n');

  let currentBullet = '';
  let currentParagraph = '';
  let firstParagraphProcessed = false;

  function flushBullet() {
    if (!currentBullet) return;

    if (containsReadMore(currentBullet)) {
      const parts = splitReadMore(currentBullet);
      for (const part of parts) {
        addBullet(part);
      }
    } else {
      addBullet(currentBullet);
    }

    currentBullet = '';
  }

  function flushParagraph() {
    if (!currentParagraph) return;

    if (containsReadMore(currentParagraph)) {
      const parts = splitReadMore(currentParagraph);
      for (const part of parts) {
        addBullet(part);
      }
    } else {
      if (!firstParagraphProcessed) {
        addBody(currentParagraph);
        firstParagraphProcessed = true;
      } else {
        addBullet(currentParagraph);
      }
    }

    currentParagraph = '';
  }

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = cleanLine(rawLine);

    if (!line) {
      flushParagraph();
      continue;
    }

    if (isReferToLine(rawLine)) {
      flushBullet();
      flushParagraph();
      continue;
    }

    if (isGlobalTitle(line)) continue;

    if (/release notes?\s+for/i.test(line)) {
      flushBullet();
      flushParagraph();
      const category = getReleaseTitleCategory(line);
      addProductHeading(category);
      continue;
    }

    if (isUpdated(line)) {
      flushBullet();
      flushParagraph();
      continue;
    }

if (isPlatformRelease(line) || isReleaseDate(line)) {
  flushBullet();
  flushParagraph();

  if (isReleaseDate(line)) {
    addReleaseDate(line);
  }

  continue;
}

    if (isSectionHeading(line)) {
      flushBullet();
      flushParagraph();
      addSectionHeading(line);
      continue;
    }

    if (isNoUpdates(line)) {
      flushBullet();
      flushParagraph();
      addBullet(line);
      continue;
    }

    if (isEmptyBullet(rawLine)) {
      flushBullet();
      flushParagraph();
      continue;
    }

    if (isBullet(rawLine)) {
      flushParagraph();
      flushBullet();
      currentBullet = cleanText(line.replace(/^[•●▪◦]\s*/, ''));
      continue;
    }

    if (isSubHeading(lines, i)) {
      flushBullet();
      flushParagraph();
      addSubHeading(line);
      continue;
    }

    if (isProductHeading(lines, i)) {
      flushBullet();
      flushParagraph();
      addProductHeading(line);
      continue;
    }

    if (currentBullet) {
      currentBullet += ' ' + line;
      continue;
    }

    if (currentParagraph) {
      currentParagraph += ' ' + line;
    } else {
      currentParagraph = line;
    }
  }

  flushParagraph();
  flushBullet();
}

// =====================================================
// BUILD DOCUMENT
// =====================================================

addMainDocumentHeading();

for (const item of input) {
  const data = item.json;

  const releaseNotes = String(data.releaseNotes || '')
    .replace(/\r/g, '')
    .trim();

  if (!releaseNotes) continue;

  const firstLine = releaseNotes
    .split('\n')
    .map(line => cleanLine(line))
    .find(Boolean) || '';

  const isSummary =
    /Boomi Enterprise Platform\s+September\s+2026\s+Release\s+Notes/i.test(firstLine);

  if (isSummary) {
    processSummaryDocument(data);
  } else {
    processNormalDocument(data);
  }

  addSpacing(10);
}

// Remove trailing spacing
while (
  section.paragraphs.length > 0 &&
  section.paragraphs[section.paragraphs.length - 1].children?.[0]?.text === ''
) {
  section.paragraphs.pop();
}

// =====================================================
// FINAL OUTPUT
// =====================================================

output.sections.push(section);

return [
  {
    json: output
  }
];

